/* From Uiverse.io by Manish-Tamang  - Tags: card, gradients, svg, html, css */
.__UIV_SCOPE__ .wrapper {
  width: 400px;
  background: #fff;
  border-radius: 16px;
  padding: 30px;
  box-shadow: 10px 10px 15px rgba(0, 0, 0, 0.05);
}
.__UIV_SCOPE__ .wrapper header {
  height: 55px;
  display: flex;
  align-items: center;
  border: 1px solid #ccc;
  border-radius: 30px;
  position: relative;
}
.__UIV_SCOPE__ header label {
  height: 100%;
  z-index: 2;
  width: 30%;
  display: flex;
  cursor: pointer;
  font-size: 18px;
  position: relative;
  align-items: center;
  justify-content: center;
  transition: color 0.3s ease;
}
.__UIV_SCOPE__ #tab-1:checked ~ header .tab-1,
.__UIV_SCOPE__ #tab-2:checked ~ header .tab-2,
.__UIV_SCOPE__ #tab-3:checked ~ header .tab-3 {
  color: #fff;
}
.__UIV_SCOPE__ header label:nth-child(2) {
  width: 40%;
}
.__UIV_SCOPE__ header .slider {
  position: absolute;
  height: 85%;
  border-radius: inherit;
  background: linear-gradient(145deg, #d5a3ff 0%, #77a5f8 100%);
  transition: all 0.3s ease;
}
.__UIV_SCOPE__ #tab-1:checked ~ header .slider {
  left: 0%;
  width: 90px;
  transform: translateX(5%);
}
.__UIV_SCOPE__ #tab-2:checked ~ header .slider {
  left: 50%;
  width: 120px;
  transform: translateX(-50%);
}
.__UIV_SCOPE__ #tab-3:checked ~ header .slider {
  left: 100%;
  width: 95px;
  transform: translateX(-105%);
}
.__UIV_SCOPE__ .wrapper input[type="radio"] {
  display: none;
}
.__UIV_SCOPE__ .card-area {
  overflow: hidden;
}
.__UIV_SCOPE__ .card-area .cards {
  display: flex;
  width: 300%;
}
.__UIV_SCOPE__ .cards .row {
  width: 33.4%;
}
.__UIV_SCOPE__ .cards .row-1 {
  transition: all 0.3s ease;
}
.__UIV_SCOPE__ #tab-1:checked ~ .card-area .cards .row-1 {
  margin-left: 0%;
}
.__UIV_SCOPE__ #tab-2:checked ~ .card-area .cards .row-1 {
  margin-left: -33.4%;
}
.__UIV_SCOPE__ #tab-3:checked ~ .card-area .cards .row-1 {
  margin-left: -66.8%;
}
.__UIV_SCOPE__ .row .price-details {
  margin: 20px 0;
  text-align: center;
  padding-bottom: 25px;
  border-bottom: 1px solid #e6e6e6;
}
.__UIV_SCOPE__ .price-details .price {
  font-size: 65px;
  font-weight: 600;
  position: relative;
  font-family: "Noto Sans", sans-serif;
}
.__UIV_SCOPE__ .price-details .price::before,
.__UIV_SCOPE__ .price-details .price::after {
  position: absolute;
  font-weight: 400;
  font-family: "Poppins", sans-serif;
}
.__UIV_SCOPE__ .price-details .price::before {
  content: "रू";
  left: -27px;
  top: 17px;
  font-size: 28px;
}
.__UIV_SCOPE__ .price-details .price::after {
  content: "/mon";
  right: -33px;
  bottom: 17px;
  font-size: 13px;
}
.__UIV_SCOPE__ .price-details p {
  font-size: 18px;
  margin-top: 5px;
}
.__UIV_SCOPE__ .row .features li {
  display: flex;
  font-size: 15px;
  list-style: none;
  margin-bottom: 10px;
  align-items: center;
}
.__UIV_SCOPE__ .features li i {
  background: linear-gradient(#d5a3ff 0%, #77a5f8 100%);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.__UIV_SCOPE__ .features li span {
  margin-left: 10px;
}
.__UIV_SCOPE__ .wrapper button {
  width: 100%;
  border-radius: 25px;
  border: none;
  outline: none;
  height: 50px;
  font-size: 18px;
  color: #fff;
  cursor: pointer;
  margin-top: 20px;
  background: linear-gradient(145deg, #d5a3ff 0%, #77a5f8 100%);
  transition: transform 0.3s ease;
}
.__UIV_SCOPE__ .wrapper button:hover {
  transform: scale(0.98);
}
